import { prisma,type TransactionClient } from '@nexora/database';type Db=typeof prisma|TransactionClient;const select={id:true,code:true,name:true,taxNo:true,paymentTerms:true,billingAddressId:true,status:true} as const;
export class VendorRepository{constructor(private readonly db:Db=prisma){}withDb(db:TransactionClient){return new VendorRepository(db);}async list(organizationId:string,skip:number,take:number){const where={organizationId};const[rows,total]=await Promise.all([this.db.vendor.findMany({where,orderBy:[{name:'asc'},{id:'asc'}],skip,take,select}),this.db.vendor.count({where})]);return{rows,total};}get(organizationId:string,id:string){return this.db.vendor.findFirst({where:{id,organizationId},select});}create(data:any){return this.db.vendor.create({data,select});}createContact(data:any){return this.db.vendorContact.create({data});}async updateScoped(organizationId:string,id:string,data:any){await this.db.vendor.updateMany({where:{id,organizationId},data});return this.db.vendor.findFirst({where:{id,organizationId},select:{...select,organizationId:true}});}latestPerformance(vendorId:string){return this.db.vendorPerformance.findFirst({where:{vendorId},orderBy:{createdAt:'desc'}});}listPurchaseOrders(input:{organizationId:string;vendorId:string;skip:number;take:number}){const where={organizationId:input.organizationId,vendorId:input.vendorId};return Promise.all([this.db.purchaseOrder.findMany({where,orderBy:{createdAt:'desc'},skip:input.skip,take:input.take,include:{items:true}}),this.db.purchaseOrder.count({where})]);}blacklist(tx:TransactionClient,input:{organizationId:string;vendorId:string;reason:string;riskScore:number}){return tx.vendor.update({where:{id:input.vendorId},data:{status:'BLACKLISTED',riskRating:'BLACKLISTED',riskScore:input.riskScore,blacklistedAt:new Date(),blacklistReason:input.reason},select:{...select,organizationId:true,riskRating:true,riskScore:true,blacklistedAt:true,blacklistReason:true}});}}